export const TIME_ZONE = "Europe/London";

export interface LocalTime {
  /** ISO date in Europe/London, e.g. "2026-11-14" */
  date: string;
  /** 0 = Sunday ... 6 = Saturday */
  weekday: number;
  /** Minutes since local midnight */
  minutes: number;
